import os
from typing import Any, Dict, Optional

import requests


class ContentSafetyError(Exception):
    pass


def allow_text(
    text: str,
    thresholds: Optional[Dict[str, float]] = None,
    api_key: Optional[str] = None,
    timeout: int = 15,
) -> Dict[str, Any]:
    if not text or not text.strip():
        raise ValueError("text must be a non-empty string")

    key = api_key or os.environ.get("PERSPECTIVE_API_KEY")
    if not key:
        raise ContentSafetyError("Missing Perspective API key: set PERSPECTIVE_API_KEY")

    effective_thresholds = {
        "TOXICITY": 0.8,
        "SEVERE_TOXICITY": 0.7,
        "IDENTITY_ATTACK": 0.7,
        "INSULT": 0.8,
        "PROFANITY": 0.85,
        "THREAT": 0.6,
    }
    if thresholds:
        effective_thresholds.update(thresholds)

    requested_attributes = {name: {} for name in effective_thresholds.keys()}

    response = requests.post(
        "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze",
        params={"key": key},
        json={
            "comment": {"text": text},
            "languages": ["en"],
            "requestedAttributes": requested_attributes,
            "doNotStore": True,
        },
        timeout=timeout,
    )

    if response.status_code != 200:
        raise ContentSafetyError(
            f"Perspective API error {response.status_code}: {response.text}"
        )

    data = response.json()
    attribute_scores = data.get("attributeScores", {})
    scores: Dict[str, float] = {}
    triggered: Dict[str, Dict[str, float]] = {}

    for category, threshold in effective_thresholds.items():
        category_data = attribute_scores.get(category, {})
        summary_score = (
            category_data.get("summaryScore", {}).get("value")
            if isinstance(category_data, dict)
            else None
        )
        if summary_score is None:
            continue

        score = float(summary_score)
        scores[category] = score
        if score >= float(threshold):
            triggered[category] = {
                "score": score,
                "threshold": float(threshold),
            }

    allowed = len(triggered) == 0

    return {
        "provider": "Perspective API",
        "allowed": allowed,
        "scores": scores,
        "thresholds": {k: float(v) for k, v in effective_thresholds.items()},
        "triggered": triggered,
        "raw_response": data,
    }
